function dispatchTimedx(string $lid,array $exclude=[]):?array{$lead=leadx($lid);if(!$lead||isset($lead['active'])&&!$lead['active'])return null;$cand=candidatesx($lead,$exclude,true);if(!$cand)return null;$b=$cand[0]['b'];$priority=priox($lead);$created=nx();$deadline=date('Y-m-d H:i:s',strtotime($created)+durationx($priority));$rows=jx(A);$new=['id'=>'A'.bin2hex(random_bytes(5)),'branch_id'=>$b['id'],'lead_id'=>$lid,'date'=>tdx(),'status'=>'new','note'=>'','followup_at'=>'','project_type'=>'','deal_value'=>'','seen_at'=>'','current'=>true,'priority'=>$priority,'timer_managed'=>true,'deadline_at'=>$deadline,'created_at'=>$created,'updated_at'=>''];$rows[]=$new;if(!sjx(A,$rows))return null;eventx((string)$b['id'],(string)$new['id'],$lid,'new',($priority==='urgent'?'سفارش فوری با مهلت ۲ ساعت':'سفارش معمولی با مهلت ۲۴ ساعت').' به نماینده ارسال شد');return $new;}
function normalizeTimersx(array &$rows):bool{$changed=false;foreach($rows as &$a){if(($a['current']??true)===false||($a['status']??'new')!=='new')continue;$lead=leadx((string)($a['lead_id']??''));$priority=(string)($a['priority']??'');if(!in_array($priority,['urgent','normal'],true)){$priority=priox($lead);$a['priority']=$priority;$changed=true;}if(empty($a['deadline_at'])){$base=strtotime((string)($a['created_at']??nx()))?:time();$a['deadline_at']=date('Y-m-d H:i:s',$base+durationx($priority));$a['timer_managed']=true;$changed=true;}}unset($a);return $changed;}
function tickTimersx():array{ensureTimerSettingsx();$rows=jx(A);$changed=normalizeTimersx($rows);$expired=[];$now=time();foreach($rows as &$a){if(($a['current']??true)===false||($a['status']??'new')!=='new')continue;$deadline=strtotime((string)($a['deadline_at']??''));if(!$deadline||$deadline>$now)continue;$priority=(string)($a['priority']??'normal');$a['current']=false;$a['status']='reassigned';$a['reassigned_at']=nx();$a['updated_at']=nx();$a['timer_expired']=true;$expired[]=['lead_id'=>(string)$a['lead_id'],'branch_id'=>(string)$a['branch_id'],'assignment_id'=>(string)$a['id'],'priority'=>$priority];$changed=true;}unset($a);if($changed)sjx(A,$rows);$moved=0;foreach($expired as $x){$label=$x['priority']==='urgent'?'مهلت ۲ ساعته':'مهلت ۲۴ ساعته';eventx($x['branch_id'],$x['assignment_id'],$x['lead_id'],'reassigned',$label.' بدون ثبت نتیجه تمام شد و سفارش خودکار منتقل شد');$new=dispatchTimedx($x['lead_id'],previousx($x['lead_id']));if($new)$moved++;}return ['expired'=>count($expired),'moved'=>$moved];}
function g2jx(int $gy,int $gm,int $gd):array{$gdm=[0,31,59,90,120,151,181,212,243,273,304,334];if($gy>1600){$jy=979;$gy-=1600;}else{$jy=0;$gy-=621;}$gy2=$gm>2?$gy+1:$gy;$days=365*$gy+intdiv($gy2+3,4)-intdiv($gy2+99,100)+intdiv($gy2+399,400)-80+$gd+$gdm[$gm-1];$jy+=33*intdiv($days,12053);$days%=12053;$jy+=4*intdiv($days,1461);$days%=1461;if($days>365){$jy+=intdiv($days-1,365);$days=($days-1)%365;}if($days<186){$jm=1+intdiv($days,31);$jd=1+$days%31;}else{$jm=7+intdiv($days-186,30);$jd=1+($days-186)%30;}return[$jy,$jm,$jd];}
